#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_QUERY_LEN 4096
#define MAX_FIELD_LEN 256
#define MAX_VARIABLES 32

typedef struct {
    char name[MAX_FIELD_LEN];
    char value[MAX_FIELD_LEN];
} gql_variable_t;

typedef struct {
    char endpoint[512];
    char api_key[128];
    int use_parameterized;
    int sanitize_mode;
    char allowed_chars[128];
} cloud_config_t;

static cloud_config_t g_config;

static int load_config(void) {
    const char *endpoint = getenv("CLOUD_GQL_ENDPOINT");
    const char *key = getenv("CLOUD_API_KEY");
    const char *mode = getenv("CLOUD_QUERY_MODE");
    const char *sanitize = getenv("CLOUD_SANITIZE_LEVEL");
    const char *allowed = getenv("CLOUD_ALLOWED_CHARS");

    if (!endpoint || !key) return -1;

    strncpy(g_config.endpoint, endpoint, sizeof(g_config.endpoint) - 1);
    strncpy(g_config.api_key, key, sizeof(g_config.api_key) - 1);

    g_config.use_parameterized = 1;
    if (mode && strcmp(mode, "inline") == 0) {
        g_config.use_parameterized = 0;
    }

    g_config.sanitize_mode = 2;
    if (sanitize) {
        g_config.sanitize_mode = atoi(sanitize);
    }

    strncpy(g_config.allowed_chars, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.", sizeof(g_config.allowed_chars) - 1);
    if (allowed) {
        strncpy(g_config.allowed_chars, allowed, sizeof(g_config.allowed_chars) - 1);
    }

    return 0;
}

static int is_char_allowed(char c) {
    return strchr(g_config.allowed_chars, c) != NULL;
}

static int sanitize_value(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    size_t inlen = strlen(input);

    if (g_config.sanitize_mode == 0) {
        strncpy(output, input, outlen - 1);
        output[outlen - 1] = '\0';
        return 0;
    }

    if (g_config.sanitize_mode >= 2) {
        for (i = 0; i < inlen && j < outlen - 1; i++) {
            if (is_char_allowed(input[i])) {
                output[j++] = input[i];
            }
        }
        output[j] = '\0';
        return 0;
    }

    /* sanitize_mode == 1: escape quotes only */
    for (i = 0; i < inlen && j < outlen - 2; i++) {
        if (input[i] == '"' || input[i] == '\\') {
            output[j++] = '\\';
        }
        output[j++] = input[i];
    }
    output[j] = '\0';
    return 0;
}

static int build_parameterized_query(const char *operation,
                                      gql_variable_t *vars, int nvar,
                                      char *query_buf, size_t buflen) {
    int written = snprintf(query_buf, buflen,
        "{\"query\":\"query Op($v0: String!) { %s(filter: $v0) { id name status } }\","
        "\"variables\":{", operation);

    for (int i = 0; i < nvar && written < (int)buflen; i++) {
        char safe_val[MAX_FIELD_LEN];
        sanitize_value(vars[i].value, safe_val, sizeof(safe_val));
        written += snprintf(query_buf + written, buflen - written,
            "\"%s\":\"%s\"%s", vars[i].name, safe_val, (i < nvar-1) ? "," : "");
    }
    written += snprintf(query_buf + written, buflen - written, "}}");
    return written;
}

static int build_inline_query(const char *operation,
                               gql_variable_t *vars, int nvar,
                               char *query_buf, size_t buflen) {
    char safe_val[MAX_FIELD_LEN];

    if (nvar < 1) return -1;

    sanitize_value(vars[0].value, safe_val, sizeof(safe_val));

    int written = snprintf(query_buf, buflen,
        "{\"query\":\"{ %s(filter: \\\"%s\\\") { id name status } }\"}",
        operation, safe_val);
    return written;
}

int cloud_infra_query(const char *resource_type, const char *filter_value) {
    char query_buf[MAX_QUERY_LEN];
    gql_variable_t vars[1];

    if (load_config() != 0) {
        fprintf(stderr, "Configuration error\n");
        return -1;
    }

    strncpy(vars[0].name, "v0", MAX_FIELD_LEN - 1);
    strncpy(vars[0].value, filter_value, MAX_FIELD_LEN - 1);
    vars[0].value[MAX_FIELD_LEN - 1] = '\0';

    int result;
    if (g_config.use_parameterized) {
        result = build_parameterized_query(resource_type, vars, 1, query_buf, sizeof(query_buf));
    } else {
        result = build_inline_query(resource_type, vars, 1, query_buf, sizeof(query_buf));
    }

    if (result < 0) return -1;

    printf("[DEBUG] Sending to %s:\n%s\n", g_config.endpoint, query_buf);
    /* In production: send query_buf to g_config.endpoint via HTTPS */
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <resource_type> <filter>\n", argv[0]);
        return 1;
    }
    return cloud_infra_query(argv[1], argv[2]);
}
